if(data.flow_mode=='HUB' || data.flow_mode=='SKILL') {
    if(!data.default_system_prompt) {
        data.default_system_prompt="${original_prompt}";
    }
    else if(data.default_system_prompt.indexOf("original_prompt")<0) {
        data.default_system_prompt="${original_prompt}\n"+data.default_system_prompt;
    }
    if(!data.enable_tools || data.enable_tools==0) {
        data.enable_tools=1;
    } 
}
else {
    if(data.default_system_prompt && data.default_system_prompt.indexOf("original_prompt")>=0) {
        data.default_system_prompt=data.default_system_prompt.replace("${original_prompt}","");
